83	  readonly timer: number;
84	  /** The move being performed, while `action` is `attack`. */
85	  readonly moveId: string | null;
86	  /** The current move already connected (hit, block or grab); a move connects once. */
87	  readonly moveHit: boolean;
88	  /** Crouching stance while grounded (crouch, a crouching move, a crouching block or hit). */
89	  readonly crouching: boolean;
90	  /** Damaging hits taken in the current combo. */
91	  readonly combo: number;
92	  /** Last frame's input bits, to find newly pressed buttons. */
93	  readonly held: number;
94	  readonly buffer: InputBuffer;
95	  /** The fighter's kit (§9): which two specials U and I start. Fixed for the duel. */
96	  readonly kit: KitId;
