145	export interface DuelStartOptions {
146	  readonly seed?: number;
147	  /** Both fighters' starting x; by default `startGap` apart about the arena's centre. */
148	  readonly x?: readonly [number, number];
149	  /** Both fighters' kits; by default the Duelist's. */
150	  readonly kits?: readonly [KitId, KitId];
151	}
152	
153	const EMPTY_BUFFER: InputBuffer = { light: 0, heavy: 0, special1: 0, special2: 0, dash: 0 };
154	
155	/** Both fighters grounded, facing each other, with full health and stamina (§6). */
156	export function createDuelState(config: DuelConfig, options: DuelStartOptions = {}): DuelState {
157	  const { arena, rules, fighter } = config.moveset;
158	  const seed = options.seed ?? 0;
159	  if (!Number.isInteger(seed)) throw new RangeError(`seed must be an integer, got ${seed}`);
160	  const centre = arena.width / 2;
161	  const [x0, x1] = options.x ?? [centre - arena.startGap / 2, centre + arena.startGap / 2];
162	  for (const x of [x0, x1]) {
163	    if (!Number.isSafeInteger(x) || x < fighter.pushbox.halfWidth || x > arena.width - fighter.pushbox.halfWidth) {
164	      throw new RangeError(`start position ${x} is not an integer inside the walls`);
165	    }
166	  }
167	  const kits = options.kits ?? ["duelist", "duelist"];
168	  for (const kit of kits) {
169	    if (!(KIT_IDS as readonly string[]).includes(kit)) throw new RangeError(`unknown kit "${String(kit)}"`);
170	  }
171	  const create = (x: number, facing: Facing, kit: KitId): FighterState => ({
172	    x,
173	    y: 0,
174	    vx: 0,
175	    vy: 0,
176	    facing,
177	    health: rules.maxHealth,
178	    stamina: rules.maxStamina,
179	    staminaIdle: 0,
180	    action: "idle",
181	    actionFrame: 0,
182	    timer: 0,
183	    moveId: null,
184	    moveHit: false,
185	    crouching: false,
186	    combo: 0,
187	    held: 0,
188	    buffer: EMPTY_BUFFER,
189	    kit,
190	    bolt: null,
191	    zone: null,
192	    obscured: false,
193	  });
194	  const facing0: Facing = x1 >= x0 ? 1 : -1;
195	  return {
196	    movesetVersion: movesetVersion(config.moveset),
197	    frame: 0,
198	    phase: "round",
199	    rng: seed >>> 0,
200	    fighters: [create(x0, facing0, kits[0]), create(x1, facing0 === 1 ? -1 : 1, kits[1])],
201	    events: [],
202	    result: null,
203	  };
204	}
205	
206	const TIMED: ReadonlySet<FighterAction> = new Set(["dash", "backdash", "attack", "hitstun", "blockstun", "stagger", "throw-break", "knockdown"]);
207	
208	/** Whether the fighter can start something on the next frame: free, or at the end of a timed action on the ground. */
209	export function canAct(fighter: FighterState): boolean {
210	  if (fighter.action === "idle" || fighter.action === "walk" || fighter.action === "crouch") return true;
211	  return TIMED.has(fighter.action) && fighter.timer === 0 && fighter.y === 0 && fighter.vy === 0;
212	}
213	
214	export function findMove(moveset: DuelMoveset, id: string): DuelMove {
215	  const move = moveset.moves.find((candidate) => candidate.timing.id === id);
216	  if (move === undefined) throw new Error(`unknown move "${id}"`);
217	  return move;
218	}
219	
220	/** The move frame a fighter executes on the next step, or 0 when it is not attacking. */
221	export function currentMoveFrame(fighter: FighterState): number {
222	  return fighter.action === "attack" ? fighter.actionFrame + 1 : 0;
223	}
224	
225	export function moveDuration(move: DuelMove): number {
226	  return move.timing.startup + move.timing.active + move.timing.recovery;
227	}
228	
229	/** The fighter's two specials (§9): its kit's, from the moveset. */
230	export function kitOf(moveset: DuelMoveset, fighter: FighterState): DuelKit {
231	  return moveset.kits[fighter.kit];
232	}
