106:describe("the Duelist mirror without kits", () => {
107:  it("covers at least 5,000 frames before the results, with guarding, throws, escapes and guard breaks", () => {
108:    expect(GOLDEN.reduce((sum, duel) => sum + duel.frames, 0)).toBeGreaterThanOrEqual(5000);
109:    const kinds = new Set<string>();
110:    for (const duel of GOLDEN) {
111:      const players = mirrorPlayers(duel.seed);
112:      let state = createDuelState(config, { seed: duel.seed });
113:      while (state.result === null) {
114:        state = stepDuel(config, state, players(state));
115:        for (const event of state.events) kinds.add(event.kind);
116:      }
117:    }
118:    expect([...kinds].sort()).toEqual(["block", "grab", "guard-break", "hit", "throw", "throw-escape"]);
119:    expect(GOLDEN.map((duel) => duel.result.reason).sort()).toEqual(["ko", "ko", "timeout"]);
120:  });
