130:      if (hashState(projected) !== duel.hashes.slice(16 * frame, 16 * frame + 16)) {
131:        // Show the difference against the last checkpoint's frame first, then fail on this one.
132:        expect(hashState(projected), `frame ${frame} (last checkpoint ${300 * Math.floor(frame / 300)})`).toBe(duel.hashes.slice(16 * frame, 16 * frame + 16));
133:      }
134:      for (const fighter of state.fighters) {
135:        expect(Object.keys(fighter).sort()).toEqual([...LEGACY_FIGHTER_FIELDS, ...Object.keys(KIT_FIELDS)].sort());
136:        expect(fighter).toMatchObject(KIT_FIELDS);
137:      }
138:    }
139:    expect(state.result).toEqual(duel.result);
140:    expect(state.movesetVersion).toBe(MOVESET_VERSION);
141:  });
