1	import { describe, expect, it } from "vitest";
2	import {
3	  createDuelState,
4	  defaultDuelConfig as config,
5	  duelInput as I,
6	  FEINT_REAPPEARANCE_FRAMES,
7	  fighterTells,
8	  findMove,
9	  strikesWithHitbox,
10	  traceDuel,
11	  type DuelInputs,
12	  type DuelState,
13	  type FighterState,
14	  type KitId,
15	} from "./index.js";
16	
17	const U = I("special1");
18	const SCREEN = I("special2");
19	const LIGHT = I("light");
20	const feint = findMove(config.moveset, "feint-dash");
21	const screen = findMove(config.moveset, "smoke-screen");
22	/** The dash: the feint's startup and active frames. */
23	const DASH = feint.timing.startup + feint.timing.active;
24	/** The feint's last frame. */
25	const END = DASH + feint.timing.recovery;
26	
27	function duel(kits: readonly [KitId, KitId], x0: number, x1: number, patch0: Partial<FighterState> = {}, patch1: Partial<FighterState> = {}): DuelState {
28	  const state = createDuelState(config, { x: [x0, x1], kits });
29	  return { ...state, fighters: [{ ...state.fighters[0], ...patch0 }, { ...state.fighters[1], ...patch1 }] };
30	}
31	
32	function hold(frames: number, p1 = 0, p2 = 0): DuelInputs[] {
33	  return Array.from({ length: frames }, () => [p1, p2] as const);
34	}
35	
36	/** `frames` of neutral input with the given presses: `[frame, p1, p2]` (frames count from 1). */
37	function presses(frames: number, ...at: readonly (readonly [number, number, number])[]): DuelInputs[] {
38	  const inputs = hold(frames);
39	  for (const [frame, p1, p2] of at) inputs[frame - 1] = [p1, p2];
40	  return inputs;
41	}
42	
43	function run(state: DuelState, inputs: readonly DuelInputs[]): DuelState[] {
44	  return traceDuel(config, state, inputs);
45	}
