176	function randomKitInputs(seed: number, frames: number): DuelInputs[] {
177	  let rng = seed;
178	  const draw = (bound: number) => {
179	    const drawn = nextInt(rng, bound);
180	    rng = drawn.state;
181	    return drawn.value;
182	  };
183	  const held = [0, 0];
184	  const left = [0, 0];
185	  const inputs: DuelInputs[] = [];
186	  for (let frame = 0; frame < frames; frame++) {
187	    for (const player of [0, 1] as const) {
188	      if (left[player] === 0) {
189	        const back = player === 0 ? I("left") : I("right");
190	        const forward = player === 0 ? I("right") : I("left");
191	        const moves = [0, back, back, back | I("down"), forward, forward, forward, I("down"), I("up"), I("up") | forward, I("up") | back, I("dash"), back | I("dash")];
192	        const attacks = [LIGHT, LIGHT, HEAVY, I("down", "heavy"), forward | HEAVY, I("down", "light"), U, U, SPECIAL2, SPECIAL2, I("light", "heavy")];
193	        const attack = draw(100) < 25;
194	        held[player] = attack ? attacks[draw(attacks.length)]! : moves[draw(moves.length)]!;
195	        left[player] = attack ? 1 + draw(2) : 1 + draw(20);
196	      }
197	      left[player]!--;
198	    }
199	    inputs.push([held[0]!, held[1]!]);
200	  }
201	  return inputs;
202	}
